const OFFICIAL_TO_B_SIDE = {
  getCandles: "multiKline",
  getTrades: "singleTick",
  getEtfHoldings: "relationList",
};

export const OFFICIAL_API_OPERATIONS = OFFICIAL_API_OPERATION_FACTS.map((operation) => {
  const bSideRouteId = OFFICIAL_TO_B_SIDE[operation.id] ?? null;
  return {
    ...operation,
    bSideRouteId,
    v2Migration: bSideRouteId
      ? "b_side_mapped"
      : operation.currentMcp === "missing" ? "blocked" : "legacy_compat",
  };
});

