const LOCAL_CATALOG_TOOL_NAMES = new Set([
  "resolve_instrument",
  "list_instruments",
  "list_industries",
  "list_industry_components",
  "search_metrics",
  "describe_metric",
  "search_api_catalog",
]);

export const SEMANTIC_TOOLS = SEMANTIC_TOOL_CANDIDATES.map((tool) => {
  const bSideRoute = B_SIDE_ROUTES.find((route) => route.tool === tool.name);
  if (bSideRoute) {
    return { ...tool, sources: [`b_side:${bSideRoute.keyRef}`], v2Availability: "b_side_mapped" };
  }
  if (LOCAL_CATALOG_TOOL_NAMES.has(tool.name)) {
    return { ...tool, v2Availability: "local_catalog" };
  }
  if (tool.name === "call_api_operation") {
    return { ...tool, sources: ["b_side_registry"], v2Availability: "b_side_router" };
  }
  return {
    ...tool,
    sources: tool.sources.map((source) => source === "official"
      ? "contract:official"
      : source === "internal" ? "candidate:internal" : source),
    v2Availability: "blocked",
  };
});
